<?php require_once __DIR__ . '/../includes/bootstrap.php';$u=require_login('employer');$p=database();$id=(int)($_GET['job_id']??$_POST['job_id']??0);$own=$p->prepare('SELECT title FROM jobs WHERE id=? AND employer_id=?');$own->execute([$id,$u['id']]);$job=$own->fetch();if(!$job)exit('Job not found.');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$status=posted('status');if(in_array($status,['submitted','under_review','shortlisted','interview','selected','rejected','withdrawn'],true))$p->prepare('UPDATE applications a JOIN jobs j ON j.id=a.job_id SET a.status=? WHERE a.id=? AND j.employer_id=?')->execute([$status,(int)$_POST['application_id'],$u['id']]);redirect('applicants.php?job_id='.$id);}$s=$p->prepare('SELECT a.*,js.full_name,u.email,qa.percentage FROM applications a JOIN job_seekers js ON js.user_id=a.seeker_id JOIN users u ON u.id=js.user_id JOIN quiz_attempts qa ON qa.id=a.qualifying_attempt_id WHERE a.job_id=?');$s->execute([$id]);page_header('Applicants');?><h1>Applicants: <?=e($job['title'])?></h1><table><tr><th>Candidate</th><th>Quiz</th><th>Status</th><th>Update</th></tr><?php foreach($s as $a):?><tr><td><?=e($a['full_name'])?><br><span class="meta"><?=e($a['email'])?></span></td><td><?=e($a['percentage'])?>%</td><td><?=status_label($a['status'])?></td><td><form method="post"><input type="hidden" name="csrf_token" value="<?=csrf_token()?>"><input type="hidden" name="job_id" value="<?=$id?>"><input type="hidden" name="application_id" value="<?=$a['id']?>"><select name="status"><?php foreach(['submitted','under_review','shortlisted','interview','selected','rejected','withdrawn'] as $status):?><option <?=$a['status']===$status?'selected':''?>><?=$status?></option><?php endforeach;?></select><button class="small">Save</button></form></td></tr><?php endforeach;?></table><?php page_footer(); ?>